window.ScripturaLexicons.BDAG_PART_0365 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-01\" data-source=\"BDAG\" data-search=\"τύχη, ης, ἡ substantivo feminino fortuna; acaso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τύχη, ης, ἡ</td><td>substantivo feminino</td><td>fortuna; acaso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-02\" data-source=\"BDAG\" data-search=\"Τυχικός, οῦ, ὁ nome próprio masculino Tíquico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τυχικός, οῦ, ὁ</td><td>nome próprio masculino</td><td>Tíquico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-03\" data-source=\"BDAG\" data-search=\"τυχόν advérbio remissão a τυγχάνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τυχόν</td><td>advérbio</td><td>remissão a τυγχάνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-04\" data-source=\"BDAG\" data-search=\"ὕαινα, ης, ἡ substantivo feminino hiena BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕαινα, ης, ἡ</td><td>substantivo feminino</td><td>hiena</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-05\" data-source=\"BDAG\" data-search=\"ὑακίνθινος, ίνη, ινον adjetivo de cor de jacinto; azul-escuro; violeta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑακίνθινος, ίνη, ινον</td><td>adjetivo</td><td>de cor de jacinto; azul-escuro; violeta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-06\" data-source=\"BDAG\" data-search=\"ὑάκινθος, ου, ὁ substantivo masculino jacinto; pedra preciosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑάκινθος, ου, ὁ</td><td>substantivo masculino</td><td>jacinto; pedra preciosa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-07\" data-source=\"BDAG\" data-search=\"ὑάλινος, η, ον adjetivo de vidro; transparente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑάλινος, η, ον</td><td>adjetivo</td><td>de vidro; transparente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-08\" data-source=\"BDAG\" data-search=\"ὕαλος, ου, ἡ substantivo feminino cristal; vidro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕαλος, ου, ἡ</td><td>substantivo feminino</td><td>cristal; vidro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-09\" data-source=\"BDAG\" data-search=\"ὑβρίζω verbo maltratar; insultar; ultrajar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑβρίζω</td><td>verbo</td><td>maltratar; insultar; ultrajar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-10\" data-source=\"BDAG\" data-search=\"ὕβρις, εως, ἡ substantivo feminino insolência; ultraje; dano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕβρις, εως, ἡ</td><td>substantivo feminino</td><td>insolência; ultraje; dano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-11\" data-source=\"BDAG\" data-search=\"ὑβριστής, οῦ, ὁ substantivo masculino pessoa violenta; insolente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑβριστής, οῦ, ὁ</td><td>substantivo masculino</td><td>pessoa violenta; insolente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-12\" data-source=\"BDAG\" data-search=\"ὑγεία substantivo feminino saúde; variante de ὑγίεια BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑγεία</td><td>substantivo feminino</td><td>saúde; variante de ὑγίεια</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-13\" data-source=\"BDAG\" data-search=\"ὑγιαίνω verbo estar são; ser correto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑγιαίνω</td><td>verbo</td><td>estar são; ser correto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-14\" data-source=\"BDAG\" data-search=\"ὑγίεια, ας, ἡ substantivo feminino saúde BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑγίεια, ας, ἡ</td><td>substantivo feminino</td><td>saúde</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-15\" data-source=\"BDAG\" data-search=\"ὑγιής, ές adjetivo são; íntegro; correto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑγιής, ές</td><td>adjetivo</td><td>são; íntegro; correto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-16\" data-source=\"BDAG\" data-search=\"ὑγρός, ά, όν adjetivo úmido; flexível; verde BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑγρός, ά, όν</td><td>adjetivo</td><td>úmido; flexível; verde</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-17\" data-source=\"BDAG\" data-search=\"ὑδρία, ας, ἡ substantivo feminino cântaro de água BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑδρία, ας, ἡ</td><td>substantivo feminino</td><td>cântaro de água</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-18\" data-source=\"BDAG\" data-search=\"ὑδροποτέω verbo beber água; preferir água BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑδροποτέω</td><td>verbo</td><td>beber água; preferir água</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-19\" data-source=\"BDAG\" data-search=\"ὑδρωπικός, ή, όν adjetivo hidrópico; que sofre de edema BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑδρωπικός, ή, όν</td><td>adjetivo</td><td>hidrópico; que sofre de edema</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0365-20\" data-source=\"BDAG\" data-search=\"ὕδωρ, ατος, τό substantivo neutro água; meio vivificante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὕδωρ, ατος, τό</td><td>substantivo neutro</td><td>água; meio vivificante</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0365-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τύχη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τύχη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hom. Hymns, Hdt.+; inscr., papiros, LXX; Jos., Bell. 4, 365, C. Ap. 2, 130; 227; Ath.) condição de ocorrer sem intervenção ou controle humano, fortuna, em nossa literatura somente como v.l. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:31</a> D por acaso, e na expressão <span class=\"greek\">ὀμνύναι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Καίσαρος</span> <span class=\"greek\">τύχην</span> jurar pela Fortuna de César (cf. Cass. Dio 44, 6; 50; 57, 8; Jos., Ant. 16, 344. Muito frequentemente nos papiros, desde POxy 483, 21 [108 d.C.] em diante) MPol 9:2; 10:1.—Sobre <span class=\"greek\">Τύχη</span> e seu culto, v. UvonWilamowitz-Moellendorff, Der Glaube der Hellenen2 ’55, 298–305.—B. 1096. Schmidt, Syn. IV 364–76. DELG s.v. <span class=\"greek\">τυγχάνω</span>. DDD s.v. Fortuna. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τυχικός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τυχικός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (inscr., p. ex., nove vezes nas de Magnésia; Hemer, Acts 236.—Sobre o acento, v. KLipsius, Gramm. Untersuchungen über die biblische Gräz. 1863, 30; Tdf., Proleg. 103) Tíquico, homem da província da Ásia que acompanhou Paulo em sua viagem a Jerusalém com a coleta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:4</a>. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:21</a> é chamado <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀγαπητὸς</span> <span class=\"greek\">ἀδελφὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πιστὸς</span> <span class=\"greek\">διάκονος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, e em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:7</a> acrescenta-se a estes <span class=\"greek\">σύνδουλος</span>. Em ambas as passagens, ele deve informar os destinatários da carta acerca do apóstolo. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:12</a> é enviado a Éfeso. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:12</a> propõe-se enviá-lo ou enviar Ártemas a Tito em Creta. V. também Eph subscr.; Col subscr.—Cf. DELG s.v. <span class=\"greek\">τυγχάνω</span>. LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τυχόν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τυχόν</span> adv. v. <span class=\"greek\">τυγχάνω</span> 2c.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕαινα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕαινα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> hiena (assim Hdt. et al.; PAth 4, 12 [III d.C.]; Sir 13:18; Jer 12:9), mencionada como animal impuro cuja carne os israelitas não tinham permissão de comer (mas não há proibição específica no AT) B 10:7 (para a extraordinária interpretação aqui representada, v. Windisch ad loc; também Diod S 32, 12, 2, relato de escritores mitológicos que sustentam, acerca da hiena, <span class=\"greek\">ἄρρενας</span> <span class=\"greek\">ἅμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θηλείας</span> <span class=\"greek\">ὑπάρχειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐνιαυτὸν</span> <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">ὀχεύειν</span>=serem ora machos, ora fêmeas, e em anos alternados terem relações sexuais entre si; Aesop, Fab. 242; 243 P.=405; 406 H.; Cyranides p. 74, 14–16; Horapollo 2, 69). OKeller, Antike Tierwelt 1909–13, I 152–57; NHenkel, Studien zum Physiologus im Mittelalter ’76, 175 (referências).—BHHW II 755. Pauly-W. Suppl. IV 1924, 761–68. DELG s.v. <span class=\"greek\">ὗς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑακίνθινος, ίνη, ινον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑακίνθινος</span>, <span class=\"greek\">ίνη</span>, <span class=\"greek\">ινον</span> (<span class=\"greek\">ὑάκινθος</span>; Hom.+; PSI 183, 5; LXX; JosAs 18:5 cód. A [p. 68, 1 Bat.] <span class=\"greek\">λίθος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span>; Philo, Spec. Leg. 1, 94; Jos., Ant. 3, 165) de cor de jacinto, isto é, azul-escuro (vermelho-escuro?) com <span class=\"greek\">πύρινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:17</a> ou violeta <span class=\"greek\">τίς</span> <span class=\"greek\">νήσει</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑακίνθιον</span> (lançaram sortes para determinar) quem tecerá a cor de jacinto GJs 10:2 (seguido de <span class=\"greek\">κόκκινον</span> e <span class=\"greek\">πορφύραν</span>).—DELG s.v. <span class=\"greek\">ὑάκινθος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑάκινθος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑάκινθος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (v. verbete precedente; já em Hom. como nome de flor) o jacinto (jacinth ou hyacinth) (Peripl. Eryth. 56 [gênero indeterminado]; Galen XIII 970; Ptolem. 7, 4, 1; Heliod. 2, 30, 3 [nele claramente fem.]; Achilles Tat. 2, 11, 3 [gênero indeterminado]; o <span class=\"greek\">λίθος</span> <span class=\"greek\">ἡλίου</span> Cat. Cod. Astr. IX/2 p. 152, 18.—Na LXX; TestSol 21:2; JosAs 2:15 al. e em Philo e Joseph. [Ant. 3, 164] entende-se tecido de cor de jacinto), pedra preciosa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:20</a>, talvez de cor azul (Michel Psellus, em Lapidaires p. 203, linha 79f <span class=\"greek\">θαλαττόχρω</span> ‘de cor marinha’), algo semelhante à safira (mas v. v. 19); sobre ela v. OED s.v. hyacinth 1ab. Os antigos frequentemente a transformavam em gemas (Pliny, NH 37, 9, 41f).—Para a literatura, v. s.v. <span class=\"greek\">ἀμέθυστος</span>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑάλινος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑάλινος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὕαλος</span>; desde Corinna [VI a.C.] 36 Page [42 Diehl]; SIG 1106, 153; PPetr III, 42 H 7, 3 [III a.C.]; POxy 1740, 30) de vidro, transparente como vidro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:6</a>; 15:2ab.—DELG s.v. <span class=\"greek\">ὕαλος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕαλος, ου, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕαλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (v. verbete precedente; assim desde Hdt. 3, 24 [<span class=\"greek\">ὕελος</span>]; Aristoph.; Pla.; PFay 134, 4), raramente <span class=\"greek\">ὁ</span> (Theophr., Lapid. 49 [<span class=\"greek\">ὕελ</span>.]; B-D-F §49, 1; Mlt-H. 67; 124.—Job 28:17 não se pode determinar o gênero)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> algum tipo de pedra cristalina, cristal (Hdt. 3, 24 et al.) <span class=\"greek\">ὕαλ</span>. <span class=\"greek\">καθαρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:18</a>. <span class=\"greek\">ὕαλ</span>. <span class=\"greek\">διαυγής</span> v. 21 ambos com ênfase na transparência. Se a pedra é que se tem em vista, o símile refere-se à sua qualidade translúcida, mas nestas duas passagens <span class=\"greek\">ὕ</span>. pode também referir-se a</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> substância translúcida à base de silicato, vidro (Pla. et al.; com <span class=\"greek\">χρυσίον</span>; cf. Job 28:17) assim NRSV e REB em ambas as passagens.—Sobre a fabricação de vidro na Antiguidade, v. SGoldstein, ‘Glass’: ISBE II 475–77 (literatura). B. 620.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑβρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑβρίζω</span> fut. 3 sg. <span class=\"greek\">ὑβρίσει</span> (TestBenj 5:4); 1 aor. <span class=\"greek\">ὕβρισα</span>. Pass.: 1 fut. <span class=\"greek\">ὑβρισθήσομαι</span>; 1 aor. <span class=\"greek\">ὑβρίσθην</span>; perf. 3 sg. <span class=\"greek\">ὕβρισται</span> (Mel.) (de <span class=\"greek\">ὕβρις</span>, v. também <span class=\"greek\">ὑβριστής</span>; Hom.+) em nossa literatura somente transitivo. tratar de modo insolente ou malicioso, maltratar, escarnecer de, insultar (Aristot., De Rhet. 2, 2 <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ὕβρις</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πράττειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λέγειν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οἷς</span> <span class=\"greek\">αἰσχύνη</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πάσχοντι</span>=insolência significa fazer e dizer coisas que acarretam vergonha à vítima; cf. Demosth. 21, 48 uma pessoa humanitária não maltrata nem mesmo escravos) <span class=\"greek\">τινά</span> alguém (frequentemente nos papiros [Mayser II/2 p. 303; referências para a passiva também aqui]) maltratar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:6</a> (com <span class=\"greek\">ἀποκτείνω</span> POxy 903, 5f [IV d.C.]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:5</a>. Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:11</a> v.l.; Dg 5:15 (com <span class=\"greek\">λοιδορεῖσθαι</span>; cf. SIG 1109, 74; 76; 78 [178 d.C.]; TestBenj 5:4); Hs 6, 3, 4; insultar (ParJer 5:20; Jos., Ant. 4, 187; Just., A I, 4, 9) com palavras <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ὑβρίζεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:45</a>; por sua conduta ultrajar, afrontar algo <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> 2 Cl 14:4a. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span> 14:4b (cf. Jos., Bell. 3, 371 [<span class=\"greek\">θεοῦ</span>] <span class=\"greek\">τὸ</span> <span class=\"greek\">δῶρον</span>, Ant. 9, 257 <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>; Theoph. Ant. 3, 30 [p. 268, 30]); proceder presunçosamente com <span class=\"greek\">αὐτοὺς</span> (<span class=\"greek\">χλευάζετε</span> <span class=\"greek\">καὶ</span>) <span class=\"greek\">ὑβρίζετε</span> Dg 2:7.—DELG s.v. <span class=\"greek\">ὕβρις</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕβρις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕβρις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (v. verbetes precedente e seguinte; Hom.+)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> qualidade ou estado de ser insolente, insolência, arrogância, sentido ativo (Appian, Basil. 5 §2 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὕβριν</span>=por arrogância; Pr 11:2; 29:23; Is 9:8; Philo, Spec. Leg. 3, 186; Jos., Ant. 6, 61; Tat., Ath.) <span class=\"greek\">ὕβρ</span>. <span class=\"greek\">ὑπερηφάνων</span> 1 Cl 59:3 (<span class=\"greek\">ὕβρ</span>. com <span class=\"greek\">ὑπερηφανία</span>: Ael. Aristid. 28, 101 K.=49 p. 524 D.; Paroem. Gr.: Zenob. [II d.C.] 5, 44. Também <span class=\"greek\">ὑβριστικῶς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὑπερηφάνως</span> Diod S 16, 41, 2).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> experiência de sofrer insolência, vergonha, insulto, maus-tratos, sentido passivo (PEleph 1, 8 [311 a.C.] <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὕβρει</span>=por insulto, por ultraje; PMagd 24 verso; PsSol 2:26f; JosAs 28:14 Philonenko [Bat. p. 84, 7]; SibOr 3, 529; Philo, In Flacc. 58; Just.; Celsus 4, 46) <span class=\"greek\">ὕβριν</span> <span class=\"greek\">ὑποφέρειν</span> Hm 8:10. <span class=\"greek\">ὕβριν</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινι</span> causar dano a alguém Hs 9, 11, 8 (JosAs 23:13). Pl. maus-tratos (Polyb. 6, 8, 5; 10, 37, 8; 11, 5, 7; Sb 5235, 12 [I d.C.] <span class=\"greek\">ὕβρεις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πληγάς</span>; PLond II, 358, 8 p. 172 [II d.C.]; Sir 10:8; SibOr 4, 164.—‘Castigos’ Theoph. Ant. 2, 25 [p. 162, 7]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:10</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> dano causado pelo emprego de força, fig. dificuldade, desastre, dano causado pelos elementos naturais (Pind., P. 1, 72 [140]; Anth. Pal. 7, 291, 4 <span class=\"greek\">δείσασα</span> <span class=\"greek\">θαλάττης</span> <span class=\"greek\">ὕβριν</span>; Jos., Ant. 3, 133 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὄμβρων</span> <span class=\"greek\">ὕβριν</span>) com <span class=\"greek\">ζημία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:10</a> (<span class=\"greek\">μετὰ</span> <span class=\"greek\">ὕβ</span>. como SIG 780, 18; 30; 3 Macc 3:25; JosAs 7:5; Jos., Ant. 1, 60), 21. Da enfermidade de Judas <span class=\"greek\">εἰς</span> <span class=\"greek\">ὕβριν</span> para (sua) vergonha Papias (3:2).—DMacDowell, Hybris in Athens: Greece and Rome 2 ser. 23, ’76, 14–31; NFisher, Hybris and Dishonour, pt. I: ibid., 177–93; pt. II, ibid., ’79, 32–47; PMarshall, Hybrists not Gnostics in Corinth: SBLSP 23, ’84, 275–87; DCohen, Sexuality, Violence, and the Athenian Law of Hybris: Greece and Rome 38, ’91, 171–88; JHooker, The Original Meaning of <span class=\"greek\">ὕβρις</span>: Archiv f. Begriffsgeschichte 19, ’75, 125–37; v. literatura citada por CBrown, Mnemosyne 49, ’96, 7 n. 13.—Schmidt, Syn. IV 273–80. DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑβριστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑβριστής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ὑβρίζω</span>; Hom.+; LXX; GrBar 16:4; Philo; Jos., Ant. 5, 339; SibOr 2, 259) pessoa violenta, insolente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:30</a> (com <span class=\"greek\">ὑπερήφανος</span> em catálogo de vícios em Ps.-Dicaearchus p. 143 Fuhr; Heraclid. Crit., Reisebilder 1, 14 p. 80, 2 Pf. A mesma justaposição de <span class=\"greek\">ὑπερήφανος</span> e <span class=\"greek\">ὑβριστής</span> em Diod S 5, 55, 6 e Aristot., Rhet. 1390b, 33 [II, 16, 1]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:13</a>.—DELG s.v. <span class=\"greek\">ὕβρις</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγεία</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑγεία</span> (esta grafia em lugar da mais antiga <span class=\"greek\">ὑγίεια</span> aparece em papiros a partir do II d.C.: POxy 496, 10 [127 d.C.]; 497, 11; 715, 29; PTebt 298, 77; PAmh 132, 3; 18 [todos do II d.C.] e também em SIG 810, 15 [55 d.C.]; a favor de <span class=\"greek\">ὑγεῖα</span>, Schwyzer I 194; PKatz TLZ 83, ’58, 315.—EpArist 190; 237; 259; Test Napht 2:8; ParJer 7:7. Predominante em Philo; e v. Jos., Bell. 1, 647 codd. Para a LXX, v. Thackeray p. 63f.) 1 Cl 20:10.—Schweizer 101; Nachmanson 71; Crönert 34; Mayser I 92, 5; v. <span class=\"greek\">ὑγίεια</span>.—DELG s.v. <span class=\"greek\">ὑγιής</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγιαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑγιαίνω</span> (<span class=\"greek\">ὑγιής</span>; Theognis, Hdt.+; inscr., papiros, LXX, TestSol; TestJob 35, 2; Test12Patr; Philo, Joseph.; Ath., R. 2 p. 49, 30)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> estar em boa saúde física, estar são, lit. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:13</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:31</a> (Artem. 4, 22 <span class=\"greek\">οὐ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὑγιαίνουσιν</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κάμνουσιν</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">θεραπειῶν</span>); 7:10; 15:27. Como fórmula de saudação epistolar (p. ex., Ltzm., Griech. Papyri2 [=Kl. T. 14] 1910 n.º 1, 3 [=BGU 423]; 2, 3 [=BGU 846]; 8, 3 [=BGU 27]; 9, 4 [=BGU 38] e frequentemente nos papiros; cf. EpArist 41) 3J 2.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> ser são ou isento de erro, ser correto, fig. nas Epístolas Pastorais com referência ao ensino cristão: <span class=\"greek\">ὑγιαίνουσα</span> <span class=\"greek\">διδασκαλία</span> 1 Ti 1:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:9</a>; 2:1. <span class=\"greek\">ὑγιαίνοντες</span> <span class=\"greek\">λόγοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:13</a>. <span class=\"greek\">ὑγιαίνειν</span> (<span class=\"greek\">ἐν</span>) <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:13</a>; 2:2 (sobre seu emprego com o dat., cf. Jos., C. Ap. 1, 222). Cf. <span class=\"greek\">λόγος</span> <span class=\"greek\">ὑγιής</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:8</a> (<span class=\"greek\">ὑγιής</span> 2). Assim, de acordo com o uso predominante, o ensino cristão é designado como instrução correta, visto que é razoável e apela à inteligência sã (Plut., Mor. 2f <span class=\"greek\">αὗται</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">ὑγιαίνουσαι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">δόξαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀληθεῖς</span> ‘estas são opiniões sãs acerca dos deuses e verdadeiras’; Philo, Abr. 223 al. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὑγιαίνοντας</span> <span class=\"greek\">λόγους</span>; Jos., C. Ap. 1, 222 <span class=\"greek\">οἱ</span> <span class=\"greek\">ὑγιαίνοντες</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κρίσει</span> [op. <span class=\"greek\">ἀνόητοι</span>]; Ath., R. 2 p. 49, 30 <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὑγιαινούσῃ</span> <span class=\"greek\">κρίσει</span> … <span class=\"greek\">χρωμένων</span>. V. também <span class=\"greek\">ὑγιής</span> 2).—MDibelius, Hdb. exc. sobre 1 Ti 1:10.—DELG s.v. <span class=\"greek\">ὑγιής</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγίεια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑγίεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (ou jôn. <span class=\"greek\">ὑγιείη</span>, Pind., Hdt.+; inscr., papiros, LXX; Philo, Sacr. Abel. 39, Aet. M. 116; Jos, Bell. 1, 647.—Para a grafia <span class=\"greek\">ὑγεία</span> em 1 Cl 20:10, v. <span class=\"greek\">ὑγεία</span>) saúde 1 Cl 61:1; (com <span class=\"greek\">ἀπόλαυσις</span>) 20:10 v.l. (em lugar de <span class=\"greek\">ὑγείαν</span>).—DELG s.v. <span class=\"greek\">ὑγιής</span>. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγιής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑγιής</span>, <span class=\"greek\">ές</span> ac. <span class=\"greek\">ὑγιῆ</span> (Hom.+; inscr., papiros, LXX; TestSol 18:20 A; TestIss 7:9; ApcEsdr 5:13 p. 30, 13 Tdf.; Philo, Joseph.)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> relativo a estar fisicamente bem ou são, saudável, são.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> de pessoas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:10</a>; ou de seus membros individualmente (SIG 1170, 26 <span class=\"greek\">ἡ</span> <span class=\"greek\">χείρ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:5</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:10</a> v.l.; <span class=\"greek\">ὑγ</span>. <span class=\"greek\">γίνεσθαι</span> ficar são (SIG 1168, 47; 94; 102; 1169, 18 [IV a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:4</a>, 6 (v. Artem. 3, 39: ninguém diz a um homem são ‘<span class=\"greek\">ὑγιανεῖς</span>’=ficarás são), 9, 14. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ὑγιῆ</span> curar alguém, restituir a saúde a alguém (X., Mem.4, 2, 7; Just., A I, 22, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:11</a>, 15; 7:23. <span class=\"greek\">ἴσθι</span> <span class=\"greek\">ὑγιὴς</span> <span class=\"greek\">ἀπό</span> … fica curado (e livre) de … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:34</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὠτίον</span> … <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ὑγιές</span> AcPl Ha 5, 35.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> de coisas íntegras, não danificadas (Eur., Thu. et al.; inscr., papiros) de árvores Hs 8, 1, 3f; 8, 3, 1. De pedras (SIG 972, 32; 101) 9, 8, 3 (comparativo); 5; 7. <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">ὑγιῆ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> (na ressurreição) AcPlCor 2:32.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo a ser incorrupto ou correto, extensão fig. de 1: <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">ὑγιῆ</span> isto é, <span class=\"greek\">τὴν</span> <span class=\"greek\">σφραγῖδα</span> conservar intacto o selo (=batismo) Hs 8, 6, 3.—<span class=\"greek\">λόγος</span> <span class=\"greek\">ὑγιής</span> ensino ou pregação sã <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:8</a> (v. <span class=\"greek\">ὑγιαίνω</span> 2 e cf. Musonius p. 6, 2 H.; Dio Chrys. 1, 49 <span class=\"greek\">ὑγ</span>. <span class=\"greek\">λόγ</span>.; Maximus Tyr. 16, 3f <span class=\"greek\">ἀλήθειάν</span> <span class=\"greek\">γε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑγιῆ</span> <span class=\"greek\">λόγον</span>; M. Ant. 8, 30 <span class=\"greek\">ὑγιὴς</span> <span class=\"greek\">λόγος</span>, também Epict. 1, 11, 28 <span class=\"greek\">ὑγιές</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φιλοσόφων</span> <span class=\"greek\">λεγόμενον</span>; 1, 12, 5; 6; SIG 983, 5 <span class=\"greek\">γνώμην</span> <span class=\"greek\">ὑγ</span>.; Epict. 3, 9, 5 <span class=\"greek\">ὑγιῆ</span> <span class=\"greek\">δόγματα</span>; EpArist 250; Philo, Spec. Leg. 2, 164 <span class=\"greek\">ὑγ</span>. <span class=\"greek\">δόξα</span>; Jos., Ant. 9, 118 <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ὑγιὲς</span> <span class=\"greek\">φρονεῖν</span>; Just., D. 3, 3 <span class=\"greek\">ὡς</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὑγιὲς</span> <span class=\"greek\">δρῶσιν</span>).—<span class=\"greek\">ἀπόδος</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ὑγιῆ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span> <span class=\"greek\">μου</span> GJs 20:2 v.l.—B. 300. DNP V “Hygieia”, 777f. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑγρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (Hom.+; inscr., papiros, LXX; SibOr 3, 144; Just.; Ath. 22, 4, R. 17 p. 68, 29) relativo a estar em condição úmida ou flexível, úmido, flexível; de madeira fresca, verde (assim <span class=\"greek\">ὑγρότης</span> Theophr., HP 5, 9, 7; 8; Philostrat., Ep. 55 <span class=\"greek\">ὑγρός</span> de rosas frescas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:31</a> (op. <span class=\"greek\">ξηρός</span> como Dio Chrys. 80 [30], 15 e frequentemente em Philo; Jos., Ant. 4, 267).—AJeremias, Hdb. der altoriental. Geisteskultur 1913, 263ff (culto de Tamuz).—B. 1074. Schmidt, Syn. II 335–58. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑδρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> cântaro de água (assim Diocles Com. [V a.C.] 1; Aristoph., Eccl. 678, Vesp. 926; Athen. 5, 199d; 11, 462b; inscr.; POxy 502, 37; PSI 428, 89; Gen 24:14ff; TestSol 5:12; Jos., Ant. 8, 341) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:6</a> (Synes., Ep. 126 p. 261 <span class=\"greek\">ὑδρία</span> … <span class=\"greek\">κείσεται</span>), 7; 4:28.—B. 347. DELG s.v. <span class=\"greek\">ὕδωρ</span> A 4. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροποτέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑδροποτέω</span> (<span class=\"greek\">ὕδωρ</span>, <span class=\"greek\">πίνω</span>; cf. <span class=\"greek\">οἰνοποτέω</span> Pr 31:4; op. <span class=\"greek\">οἴνῳ</span> <span class=\"greek\">διαχρῆσθαι</span> Hdt. 1, 71, 2; X., Cyr. 6, 2, 26; Pla., Rep. 8, 561c; Epict. 3, 13, 21, cf. 3, 14, 4; Aelian, VH 2, 38 <span class=\"greek\">μὴ</span> <span class=\"greek\">ὁμιλεῖν</span> <span class=\"greek\">οἴνῳ</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">ὑδροποτεῖν</span>; Lucian, Bis Accus. 16; Da 1:12) preferir água como bebida, beber (somente) água, de um modo de vida abstêmio <span class=\"greek\">μηκέτι</span> <span class=\"greek\">ὑδροπότει</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">οἴνῳ</span> <span class=\"greek\">ὀλίγῳ</span> <span class=\"greek\">χρῶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:23</a>. A recomendação aparentemente se destina a contrabalançar o ascetismo extremo e a crítica concomitante aos cristãos por seu alheamento da vida pública (cf. <span class=\"greek\">ὑδροπότης</span> no sentido de ‘desmancha-prazeres’, como nosso coloquial ‘estraga-festas’, Anth. Pal. 11, 20).—DELG s.v. <span class=\"greek\">ὕδωρ</span> e <span class=\"greek\">πίνω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρωπικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑδρωπικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> que sofre de hidropisia, edema (Hippocr. et al. em escritores médicos [Hobart 24] e não médicos [p. ex. <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 3, 4; Ptolem., Apotel. 4, 9, 3; Proverbia Aesopi 95 P.; Diog. L. 4, 27; escólio a Nicander, Ther. 70 p. 10, 27]; sobre o uso, v. HCadbury, JBL 45, 1926, 205; cf. ibid. 52, ’33, 62f) <span class=\"greek\">ἄνθρωπός</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ὑδρωπικός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:2</a>.—DELG s.v. <span class=\"greek\">ὕδωρ</span> C. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0365-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕδωρ, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὕδωρ</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Hom.+; empréstimo no rabínico) água</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> em sentido material, como elemento Dg 8:2 (Ar. 5, 1f; Ath. 18, 3; v. <span class=\"greek\">στοιχεῖον</span> 1). Do oceano 1 Cl 33:3; pl. Hv 1, 3, 4 (cf. Ps 135:6, com o sing. como v.l.; JosAs 12:3; Just., A I, 60, 6). A terra (antes do Dilúvio) formada <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ὕδατος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:5</a> (cf. HDiels, Doxographi Graeci 1879 p. 276, 12 [<span class=\"greek\">Θαλῆς</span>] <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὕδατός</span> <span class=\"greek\">φησι</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἀναλύεσθαι</span>; JChaine, Cosmogonie aquatique et conflagration finale d’après 2 Pt: RB 46, ’37, 207–16. V. também Artem. 1, 77 p. 70, 6 al. <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ὕδατος</span>). Das águas do Dilúvio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:6</a>. <span class=\"greek\">σίφων</span> <span class=\"greek\">ὕδατος</span> bomba de água Hm 11:18. <span class=\"greek\">κεράμιον</span> <span class=\"greek\">ὕδατος</span> cântaro de água (v. <span class=\"greek\">κεράμιον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:10</a>. <span class=\"greek\">ποτήριον</span> <span class=\"greek\">ὕδατος</span> (Just., A I, 65, 3; 66, 4; PGen 51, 9) copo de água <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:41</a>. Água para lavar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:5</a>. Cf. Hs 9, 10, 3. Água de um poço <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:7</a> (TestAbr A 3 p. 79f [Stone p. 7f] <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φρέατος</span>); de uma fonte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:12</a> (<span class=\"greek\">γλυκὺ</span> <span class=\"greek\">ὕδωρ</span>; v. <span class=\"greek\">γλυκύς</span>, também Demetr.: 722 Fgm. 4 Jac.; ParJer 9:18; Just., D. 86, 1; Herm. Wr. 13, 17); de um curso de água <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:12</a> (cf. ParJer 6:25 <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰορδάνου</span>; Just., D. 88, 3).—<span class=\"greek\">τὸ</span> <span class=\"greek\">ὕδωρ</span> especificamente=o rio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:10</a>; =a piscina <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3f</a>, 7; =o lago <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:24</a>, pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:32</a>; 14:28f; =a fonte etc., pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:11ab</a>; cf. <span class=\"greek\">πηγαὶ</span> (<span class=\"greek\">τῶν</span>) <span class=\"greek\">ὑδάτων</span> v. 10; 14:7; 16:4 (Just. A I, 64, 1); =a torrente de montanha, pl. Hv 1, 1, 3; cf. GJs 18:3. De águas em geral, ou não definidas mais precisamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:15</a>. <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">τι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:36a</a>. Cf. vv. 38f. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:22</a>. <span class=\"greek\">ὕδατα</span> <span class=\"greek\">πολλά</span> (Ps 28:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:1</a>; <span class=\"greek\">ὕδατα</span> <span class=\"greek\">ταῦτα</span> GJs 3:2. <span class=\"greek\">φωνὴ</span> <span class=\"greek\">ὑδάτων</span> <span class=\"greek\">πολλῶν</span> o som de muitas águas (Ps 92:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:15</a>; 14:2; 19:6 (Mussies 82). <span class=\"greek\">χεόμενα</span> <span class=\"greek\">ὕδατα</span> água que se derrama Ox 840, 32f. <span class=\"greek\">γεμίσαι</span> <span class=\"greek\">ὕδωρ</span> tirar água GJs 11:1 (cf. TestAbr A 3 p. 79, 34 [Stone p. 6]).—À maneira de Num 15:16ff, da prova pela água <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλέγξεως</span> GJs 16:1. Com pão, como aquilo que é necessário para manter a vida Hs 5, 3, 7 (cf. Am 8:11; JosAs 10:2; 4 [6] Esdr [POxy 1010]); AcPl Ha 4, 4. Em contraste com vinho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:9</a> (ApcEsdr 4:27). Com sangue <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:34</a> (v. <span class=\"greek\">αἷμα</span> 1a). Cristo veio <span class=\"greek\">δι</span>’ <span class=\"greek\">ὕδατος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αἵματος</span> e <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὕδατι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἵματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:6abc</a>; cf. v. 8 (v. <span class=\"greek\">διά</span> A 1a, <span class=\"greek\">ἐν</span> 5a<span class=\"greek\">β</span> e <span class=\"greek\">ἔρχομαι</span> 1b<span class=\"greek\">α</span>). Em geral, do batismo de João com água (somente), op. <span class=\"greek\">πνεῦμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:33</a> (26, 31); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:5</a>; 11:16. Do batismo cristão, o novo nascimento <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεύματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:5</a> (sobre a originalidade da leitura <span class=\"greek\">ὕδατος</span> <span class=\"greek\">καί</span>, v. Hdb.3 ad loc.; Bultmann 98, 2; cf. Just., D. 138, 3 <span class=\"greek\">δι</span>’ <span class=\"greek\">ὕδατος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ξύλου</span>), 8 v.l. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:47</a> AcPl Ha 3, 32. <span class=\"greek\">καθαρίσας</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λουτρῷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥήματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:26</a>. <span class=\"greek\">λελουσμένοι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">ὕδατι</span> <span class=\"greek\">καθαρῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:22</a> (<span class=\"greek\">καθαρός</span> 1). Mesmo o AT aponta para a água do batismo B 11:1ab, 8ab, que Cristo consagrou por seu próprio batismo IEph 18:2. A linguagem simbólica de Hermas faz muitas alusões à água batismal: <span class=\"greek\">δι</span>’ <span class=\"greek\">ὕδατος</span> <span class=\"greek\">ἀναβαίνειν</span> Hs 9, 16, 2. <span class=\"greek\">εἰς</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">καταβαίνειν</span> m 4, 3, 1; Hs 9, 16, 6. A torre (=assembleia de Deus, igreja) é edificada <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ὑδάτων</span> Hv 3, 2, 4; 3, 3, 5ab, <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">ὕδατος</span> <span class=\"greek\">ἐσώθη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωθήσεται</span> 3, 3, 5c. Segundo D 7:1, sempre que possível, <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">ζῶν</span> água corrente (<span class=\"greek\">ζάω</span> 4) deve ser usada ao batizar. Cf. 7:2.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> meio transcendente que dá vida, água, extensão fig. de 1, com a transição assinalada por <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:10f</a>, onde (<span class=\"greek\">τὸ</span>) <span class=\"greek\">ὕδωρ</span> (<span class=\"greek\">τὸ</span>) <span class=\"greek\">ζῶν</span> (cf. JosAs 14:12; 1QH 8:7 e CD 6:4 [v. também 3:16]) é em parte água de fonte e em parte símbolo dos benefícios conferidos por Jesus (OCullmann, ThZ 4, ’48, 367f.—Quanto à imagem, cf. Sir 15:3.—Cf. 1QH 8:4). Cf. 7:38; 4:14abc (cf. Sir 24:21); IRo 7:2 (cf. OdeSol 11:6; Anacreontea 12, 7 p. 9 Preisendanz <span class=\"greek\">λάλον</span> <span class=\"greek\">ὕδωρ</span>). <span class=\"greek\">ὕδωρ</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">ζωῆς</span> água da vida (v. Hdb. exc. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:14</a>; REisler, Orphisch-dionys. Mysteriengedanken in der christl. Antike: Vorträge der Bibl. Warburg II/2, 1925, 139ff; Herm. Wr. 1, 29 <span class=\"greek\">ἐτράφησαν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀμβροσίου</span> <span class=\"greek\">ὕδατος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:6</a> (o prêmio concedido a um herói vencedor; cf. Pind., I. 6, 74); 22:1, 17. <span class=\"greek\">βεβάμμεθα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὕδασι</span> <span class=\"greek\">ζωῆς</span> Ox 840, 43f. <span class=\"greek\">ζωῆς</span> <span class=\"greek\">πηγαὶ</span> <span class=\"greek\">ὑδάτων</span> fontes de água viva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:17</a>.—SEitrem, Opferritus u. Voropfer der Griechen u. Römer 1915, 78ff, Beiträge z. griech. Religionsgesch. III 1920, 1ff; MNinck, Die Bed. des Wassers im Kult u. Leben der Alten 1921; AKing, Holy Water: A Short Account of the Use of Water for Ceremonial and Purificatory Purposes in Pagan, Jewish, and Christian Times 1926; TCanaan, Water and the ‘Water of Life’ in Palest. Superstition: JPOS 9, 1929, 57–69.—B. 35; BHHW III 2138–41 (literatura).—DELG. M-M. TW.</p></section></article>"};
